  "proposed_command": "@echo off
setlocal enabledelayedexpansion

set "source_dirs=C:\AppLogs\app1 C:\AppLogs\app2 \server01\logs\legacy"
set "dest_base=\\archive-server\\logs\\monthly"
for /f "tokens=2 delims==" %%a in ('wmic os get localdatetime /value') do set datetime=%%a
set year=%datetime:~0,4%
set month=%datetime:~4,2%
set "dest_dir=%dest_base%\%year%-%month%"

if not exist "%dest_dir%" mkdir "%dest_dir%"

for %%d in (%source_dirs%) do (
    echo Processing directory: %%d
    if exist "%%d" (
        for /r "%%d" %%f in (*.log) do (
            set "rel_path=%%~pf"
            set "rel_path=!rel�t:%%d.=!"
            set "target_path=%dest_dir%!rel_path!"
            if not exist "!target_path!" mkdir "!target_path!"
            copy "%%f" "!target_path!" >nul 2>&1
            if errorlevel 1 (
                echo Failed to copy: %%f
            ) else (
                echo Copied: %%f
            )
        )
    ) else (
        echo Warning: Source directory not accessible: %%d
    )
)

echo Archive operation completed.
exit /b 0"
}

